<script setup>
import AppealRecalculationSummary from './AppealRecalculationSummary.vue'
import RestrictionRecord from './RestrictionRecord.vue'
import {eligibilityText} from '../composables/restrictionForm.js'
import ProtectedAttachment from './ProtectedAttachment.vue'
import {getAppealAttachment} from '../api/appeal'
import {violationLabels,appealStatuses} from '../composables/appealForm.js'
defineProps({record:{type:Object,required:true}})
</script>
<template><section class="appeal-record"><h3>申诉#{{record.id}} · {{appealStatuses[record.status]||record.status}}</h3><p>提交：{{record.submitted_at}}（Asia/Shanghai）</p><p class="text">申诉说明：{{record.description}}</p><p>提交不等于审核同意，不撤销违规、不解除限制、不恢复已取消预约或使用记录。当前预约资格请以服务端核对为准。</p><section class="snapshot"><h4>提交时违规快照</h4><p>违规#{{record.violation_id}} · {{violationLabels[record.violation_snapshot.type]||record.violation_snapshot.type}} · {{record.violation_snapshot.source==='manual'?'管理员核实后登记':'系统自动事件'}} · 提交时{{record.violation_snapshot.status==='active'?'有效':record.violation_snapshot.status==='revoked'?'已撤销':record.violation_snapshot.status}}</p><p>发生：{{record.violation_snapshot.occurred_at}}；登记：{{record.violation_snapshot.registered_at}}</p><p class="text">公开事实依据：{{record.violation_snapshot.reason}}</p><p v-if="record.violation_snapshot.source==='manual'">关联预约涉及他人，不公开编号</p><p v-else-if="record.violation_snapshot.reservation_id">本人预约#{{record.violation_snapshot.reservation_id}}</p></section><p>原通知依据：{{record.notification_basis.notified_at}}；原申诉截止：{{record.notification_basis.deadline}}。这是提交所依据的通知记录，不代表已阅读或重新起算。</p><h4>申诉照片材料（{{record.attachments.length}}张）</h4><p v-if="!record.attachments.length">本次未附照片。</p><div class="attachments"><ProtectedAttachment v-for="attachment in record.attachments" :key="attachment.id" :attachment="attachment" :load-content="getAppealAttachment" /></div><section v-if="record.review"><h4>公开审核结果：{{appealStatuses[record.review.decision]||record.review.decision}}</h4><p class="text">公开理由：{{record.review.reason}}</p><p>审核登记：{{record.review.reviewed_at}} · {{record.review.reviewer_display_name}}；依据由管理员据实核实记录。</p><p>{{({revoked:'本次撤销该违规',already_revoked:'原违规此前已撤销，原撤销依据保持',unchanged:'原违规状态保持'})[record.review.violation_action]||record.review.violation_action}}。</p><AppealRecalculationSummary :items="record.review.automatic_recalculations" /></section><section v-if="record.current_eligibility"><h4>当前预约资格快照</h4><p>{{eligibilityText(record.current_eligibility)}}。</p><p>服务端核对：{{record.current_eligibility.server_now}}（{{record.current_eligibility.campus_zone}}）；批准不保证可新预约，提交时仍会复核。</p><RestrictionRecord v-for="item in record.current_eligibility.active_restrictions" :key="item.id" :record="item" /></section><h4>已登记进度</h4><ul><li v-for="event in record.events" :key="`${event.type}:${event.id}`">{{event.type==='submitted'?'本人已提交':appealStatuses[event.type]||event.type}} · {{event.occurred_at}} · {{event.actor_display_name||'记录人未提供'}}<p v-if="event.reason" class="text">公开审核理由：{{event.reason}}</p></li></ul><p v-if="record.server_now">服务端读取：{{record.server_now}}（{{record.campus_zone}}）</p></section></template>
<style scoped>.appeal-record{display:grid;gap:12px;min-width:0;overflow-wrap:anywhere}.text{white-space:pre-wrap}.snapshot{padding:12px;background:var(--surface-2);border-radius:var(--r-md);display:grid;gap:8px}.attachments{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(240px,100%),1fr));gap:12px}</style>
